import{_ as t,c as a,o as s,ae as o}from"./chunks/framework.CliRSA9F.js";const n="/images/knowledge_check.webp",w=JSON.parse('{"title":"Knowledge Check","description":"","frontmatter":{},"headers":[],"relativePath":"features/knowledge-check.md","filePath":"features/knowledge-check.md"}'),r={name:"features/knowledge-check.md"};function i(h,e,l,c,d,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="knowledge-check" tabindex="-1">Knowledge Check <a class="header-anchor" href="#knowledge-check" aria-label="Permalink to &quot;Knowledge Check&quot;">​</a></h1><h2 id="see-what-ai-assistants-actually-know-about-your-podcast" tabindex="-1">See What AI Assistants Actually Know About Your Podcast <a class="header-anchor" href="#see-what-ai-assistants-actually-know-about-your-podcast" aria-label="Permalink to &quot;See What AI Assistants Actually Know About Your Podcast&quot;">​</a></h2><p>Knowledge Check shows you what the major AI assistants believe about your show — and flags anything they get wrong. As more listeners ask ChatGPT, Claude, Perplexity, and Gemini for podcast recommendations, it matters not only that AI mentions you, but that it describes you accurately. Knowledge Check asks each assistant directly, compares its answer against your own show notes and feed, and brings back a clear list of fixes for whatever doesn&#39;t add up.</p><p><img src="'+n+'" alt="Knowledge Check Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>AI Visibility</strong> in the sidebar, then open the <strong>Knowledge Check</strong> tab.</p><h2 id="why-knowledge-accuracy-matters" tabindex="-1"><strong>Why Knowledge Accuracy Matters</strong> <a class="header-anchor" href="#why-knowledge-accuracy-matters" aria-label="Permalink to &quot;**Why Knowledge Accuracy Matters**&quot;">​</a></h2><p>Being recommended by AI is only valuable if the AI gets the details right. When a listener asks an assistant about your show, a confident but wrong answer — the wrong host name, an outdated topic, a made-up detail, or a confusion with a similarly named podcast — can send that listener elsewhere or set the wrong expectation before they ever press play.</p><p>Knowledge Check helps you find and close those gaps. Instead of guessing what AI assistants think, you get a side-by-side look at what each one actually says about your podcast, measured against the facts in your own materials.</p><h2 id="how-to-use-knowledge-check" tabindex="-1"><strong>How to Use Knowledge Check</strong> <a class="header-anchor" href="#how-to-use-knowledge-check" aria-label="Permalink to &quot;**How to Use Knowledge Check**&quot;">​</a></h2><h3 id="run-a-check" tabindex="-1"><strong>Run a Check</strong> <a class="header-anchor" href="#run-a-check" aria-label="Permalink to &quot;**Run a Check**&quot;">​</a></h3><p>Open the Knowledge Check tab and select <strong>Run a knowledge check</strong>. PodSEO asks the same plain-English question about your show to all four major AI assistants:</p><ul><li><strong>ChatGPT</strong> (OpenAI)</li><li><strong>Claude</strong> (Anthropic)</li><li><strong>Perplexity</strong></li><li><strong>Gemini</strong> (Google)</li></ul><p>Each assistant is asked twice — once based on what it already knows, and once with live web search — so you can see both what it has learned and what it finds on the live web. The check runs in the background and assembles your results when every assistant has answered.</p><h3 id="review-your-results" tabindex="-1"><strong>Review Your Results</strong> <a class="header-anchor" href="#review-your-results" aria-label="Permalink to &quot;**Review Your Results**&quot;">​</a></h3><p>When the check finishes, you&#39;ll see a summary headline telling you how many of the four assistants recognize your podcast, along with how many details disagree with your own materials.</p><p>A <strong>Your materials say</strong> reference panel sits at the top, showing what your show notes and feed actually state about your hosts, format, audience, topics, and description. This is the standard every assistant&#39;s answer is measured against, so you can see exactly where any mismatch comes from.</p><p>Below that, each assistant gets its own card showing:</p><ul><li><strong>What it knows</strong> — the hosts, topics, audience, and description it associates with your show</li><li><strong>Trained vs. Web search</strong> — toggle between what the assistant learned previously and what it finds on the live web, so you can tell whether an issue is a stale-knowledge gap or a live-web discoverability gap</li><li><strong>Mismatch flags</strong> — clear labels when an answer disagrees with your materials, such as hosts that don&#39;t match, topics that drift, an outdated description, or a made-up detail</li><li><strong>Sources</strong> — where the assistant pulled web information from, when available</li><li><strong>A verify link</strong> — open the assistant yourself to confirm what it says</li></ul><h3 id="act-on-recommended-fixes" tabindex="-1"><strong>Act on Recommended Fixes</strong> <a class="header-anchor" href="#act-on-recommended-fixes" aria-label="Permalink to &quot;**Act on Recommended Fixes**&quot;">​</a></h3><p>Knowledge Check ends with a <strong>Recommended next steps</strong> list. Each fix targets a specific gap it found and links you straight to the PodSEO page that closes it — your show notes, your description, or your website — so you can take action without hunting for where to start.</p><p>A <strong>website signals</strong> strip also shows whether your site offers the kinds of structured information that help assistants describe you accurately, so you know whether strengthening your web presence could improve future answers.</p><h2 id="how-fast-each-assistant-catches-up" tabindex="-1"><strong>How Fast Each Assistant Catches Up</strong> <a class="header-anchor" href="#how-fast-each-assistant-catches-up" aria-label="Permalink to &quot;**How Fast Each Assistant Catches Up**&quot;">​</a></h2><p>When you fix something, different assistants reflect the change on different timelines:</p><ul><li><strong>ChatGPT and Claude</strong> answer mostly from what they previously learned, so a fix you make today typically lands at their next knowledge refresh — a matter of weeks to months.</li><li><strong>Perplexity</strong> reads the live web on every question, so updates tend to show up within days.</li><li><strong>Gemini</strong> mixes stored knowledge with live search, so fixes generally land somewhere in between.</li></ul><p>Knowing this helps you set realistic expectations after making a change and decide where a fix will pay off soonest.</p><h2 id="best-practices" tabindex="-1"><strong>Best Practices</strong> <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;**Best Practices**&quot;">​</a></h2><ul><li><strong>Start with your materials.</strong> Because every mismatch is measured against your show notes and feed, accurate, complete metadata is the foundation. Make sure your host names, description, and topics reflect your show as it is today.</li><li><strong>Prioritize the clear errors.</strong> Wrong host names, confused shows, and made-up details do the most damage to listener trust — close those first.</li><li><strong>Re-check after you make changes.</strong> Knowledge Check is available to run once per week, which gives faster-updating assistants like Perplexity time to reflect your fixes before you check again.</li><li><strong>Watch the Trained vs. Web search gap.</strong> If an assistant gets you right on the live web but wrong from memory, the issue is timing. If it&#39;s wrong on both, that points to a discoverability gap worth strengthening through your web presence.</li></ul><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>Knowledge Check works alongside the rest of the AI Visibility tools to give you a complete picture of how AI sees your show:</p><ul><li><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> — tracks how often AI assistants recommend your podcast across topics</li><li><strong><a href="/features/ai-leaderboard.html">AI Leaderboard</a></strong> — shows which podcasts AI recommends most for any topic</li><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — optimizing your metadata for search also helps AI describe your show accurately</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>Knowledge Check is a paid feature. Free users see a preview of what the check covers along with an <strong>Upgrade to run a knowledge check</strong> prompt; upgrading unlocks the ability to run checks and view full results. Each podcast can run one check per week.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Run a check whenever you rebrand, change hosts, or shift your show&#39;s focus — these are exactly the moments AI is most likely to be out of date</li><li>Use the <strong>verify link</strong> on any card to confirm an assistant&#39;s answer yourself before deciding whether a fix is needed</li><li>Pair Knowledge Check with <a href="/features/ai-mentions.html">AI Mentions</a>: Mentions tells you whether AI recommends you, Knowledge Check tells you whether it describes you correctly</li></ul>',35)])])}const p=t(r,[["render",i]]);export{w as __pageData,p as default};
